<script setup>
import {computed,reactive,ref} from 'vue'
import {useRouter} from 'vue-router'
import {useAuthStore} from '../stores/auth'
import {useMarketStore} from '../stores/market'
import {COLLEGES} from '../data/seed'
import {action,money,notify} from '../lib/ui'
import Icon from '../components/Icon.vue'
const auth=useAuthStore(),market=useMarketStore(),router=useRouter(),tab=ref('products'),filter=ref('all'),busy=ref(false),pendingDelete=ref(null)
const form=reactive({displayName:auth.user.displayName,college:auth.user.college})
const mine=computed(()=>market.products.filter(p=>p.sellerId===auth.user.id)),shown=computed(()=>mine.value.filter(p=>filter.value==='all'||p.status===filter.value))
const labels={available:'正在转让',reserved:'已被预订',sold:'已找到归宿',offline:'已下架'}
async function save(){busy.value=true;try{await auth.updateProfile(form);await market.setProfile(auth.user);notify('资料已更新，很高兴重新认识你')}catch(e){notify(e.message,'error')}finally{busy.value=false}}
async function logout(){const result=await action(async()=>{await auth.logout();return true});if(result)router.replace('/')}
async function remove(){if(!pendingDelete.value)return;const result=await action(async()=>{await market.removeProduct(auth.user.id,pendingDelete.value.id);return true},'闲置已删除');if(result)pendingDelete.value=null}
</script>
<template><div class="page-width inner-page profile-page"><section class="profile-cover"><div class="profile-cover-art"></div><span class="avatar profile-avatar">{{auth.user.displayName.slice(-2)}}</span><div class="profile-identity"><span class="eyebrow">MY LITTLE CORNER</span><h1>{{auth.user.displayName}}<span>的校园角落</span></h1><p>{{auth.user.college}} · 濂溪校区 <span class="tag">{{auth.user.role==='admin'?'市集管理员':'校园同学'}}</span></p></div><button class="button outline" @click="tab='settings'"><Icon name="edit" :size="16"/>编辑资料</button></section><div class="profile-layout"><aside class="panel profile-sidebar"><button :class="{active:tab==='products'}" @click="tab='products'"><Icon name="box" :size="18"/>我的闲置<span>{{mine.length}}</span></button><RouterLink to="/orders"><Icon name="order" :size="18"/>我的订单<Icon name="chevron" :size="15"/></RouterLink><RouterLink to="/favorites"><Icon name="heart" :size="18"/>我的收藏<span>{{market.userFavorites(auth.user.id).length}}</span></RouterLink><RouterLink to="/messages"><Icon name="message" :size="18"/>我的消息<span>{{market.unreadCount(auth.user.id)}}</span></RouterLink><button :class="{active:tab==='settings'}" @click="tab='settings'"><Icon name="user" :size="18"/>个人资料</button><RouterLink v-if="auth.user.role==='admin'" to="/admin"><Icon name="admin" :size="18"/>管理市集<Icon name="chevron" :size="15"/></RouterLink><button class="logout-option" @click="logout"><Icon name="logout" :size="18"/>退出登录</button><div class="profile-sidebar-note"><Icon name="leaf" :size="33"/><p>让喜欢循环，<br>让青春留下。</p></div></aside><section v-if="tab==='products'" class="profile-content"><div class="section-heading"><div><h2>我的毕业清单</h2><p>把用心挑选过的东西，再传给有需要的人。</p></div><RouterLink to="/publish" class="button primary"><Icon name="plus" :size="17"/>发布新闲置</RouterLink></div><div class="home-tabs"><button v-for="item in [{id:'all',label:'全部'},...Object.entries(labels).map(([id,label])=>({id,label}))]" :key="item.id" :class="{active:filter===item.id}" @click="filter=item.id">{{item.label}}</button></div><div v-if="!shown.length" class="panel empty-state"><Icon name="box" :size="40"/><h3>这里还没有这一状态的闲置</h3><RouterLink to="/publish" class="text-link">发布第一件好物<Icon name="arrow" :size="17"/></RouterLink></div><article v-for="product in shown" :key="product.id" class="panel profile-product"><RouterLink :to="`/product/${product.id}`"><img :src="product.images[0]" :alt="product.title"/></RouterLink><div><span :class="['tag',product.status]">{{labels[product.status]}}</span><RouterLink :to="`/product/${product.id}`" class="profile-product-title">{{product.title}}</RouterLink><small>{{product.condition}} · {{product.college}}</small><strong class="rose">¥{{money(product.price)}}</strong></div><div class="profile-product-actions"><RouterLink v-if="!['reserved','sold'].includes(product.status)" :to="`/publish/${product.id}`" class="button outline"><Icon name="edit" :size="15"/>编辑</RouterLink><button v-if="!['reserved','sold'].includes(product.status)" class="icon-button" @click="pendingDelete=product" aria-label="删除闲置"><Icon name="trash" :size="17"/></button><RouterLink v-else to="/orders" class="text-link">查看订单<Icon name="arrow" :size="15"/></RouterLink></div></article></section><section v-else class="panel settings-form"><span class="eyebrow">NICE TO KNOW YOU</span><h2>认识更真实的你。</h2><p>你的昵称和学院，会展示在发布的闲置与聊天中。</p><form @submit.prevent="save"><label>用户名<input :value="auth.user.username" disabled/></label><label for="profile-name">昵称<input id="profile-name" v-model="form.displayName" required maxlength="20" minlength="1"/></label><label for="profile-college">学院<select id="profile-college" v-model="form.college"><option v-for="college in COLLEGES" :key="college">{{college}}</option></select></label><button class="button primary" :disabled="busy">{{busy?'正在保存…':'保存资料'}}<Icon name="check" :size="17"/></button></form></section></div><Teleport to="body"><div v-if="pendingDelete" class="modal-overlay" @click.self="pendingDelete=null"><section class="modal confirmation-modal"><Icon name="trash" :size="32"/><h2>确定删除这件闲置？</h2><p>“{{pendingDelete.title}}”将从市集中移除。</p><div class="modal-buttons"><button class="button outline" @click="pendingDelete=null">再想一想</button><button class="button primary" @click="remove">确认删除</button></div></section></div></Teleport></div></template>
